function normalize_view_area(string $area,bool $allowAll=false): string {$area=strtoupper(trim($area));if($allowAll&&($area===''||$area==='ALL'))return 'ALL';return isset(view_areas()[$area])?$area:($allowAll?'ALL':'RV');}

