function render_matrix(PDO $db,int $projectId,int $objectId=0,string $area='RV'): void {
    if(!$projectId&&$objectId){$stmt=$db->prepare('SELECT project_id FROM rollout_objects WHERE id=?');$stmt->execute([$objectId]);$projectId=(int)$stmt->fetchColumn();}
    if(!$projectId)$projectId=(int)$db->query('SELECT id FROM projects ORDER BY name LIMIT 1')->fetchColumn();
    $area=normalize_view_area($area);$dimension=catalog_dimension($area);
    $stmt=$db->prepare('SELECT * FROM projects WHERE id=?');$stmt->execute([$projectId]);$project=$stmt->fetch();
    if(!$project){echo '<div class="alert alert-danger">Projekt nicht gefunden.</div>';return;}
    $stmt=$db->prepare('SELECT * FROM rollout_objects WHERE project_id=? ORDER BY start_date,name');$stmt->execute([$projectId]);$allObjects=enrich_rollout_objects($db,$stmt->fetchAll());
    $objects=$objectId?array_values(array_filter($allObjects,fn($o)=>(int)$o['id']===$objectId)):$allObjects;if($objectId&&!$objects){$objectId=0;$objects=$allObjects;}$selectedObject=$objectId?$objects[0]:null;
    $inArea=static fn(array $service):bool=>in_array($area,(array)$service['provider_targets'],true);
    $providers=array_values(array_filter($db->query("SELECT * FROM providers WHERE active=1 ORDER BY sort_order,name")->fetchAll(),fn($p)=>$p['type']===$area));
    $stmt=$db->prepare('SELECT * FROM project_provider_contacts WHERE project_id=?');$stmt->execute([$projectId]);$projectContacts=[];foreach($stmt as $contact)$projectContacts[$contact['provider_id']]=$contact;
    $allStandardProjectServices=enrich_support_services($db,$db->query("SELECT * FROM support_services WHERE active=1 AND is_standard=1 ORDER BY name COLLATE NOCASE")->fetchAll());
    $projectClassScope=project_rollout_class_scope($db,$projectId);
    $projectFunctionalMax=$projectClassScope['functional']?$projectClassScope['functional'][count($projectClassScope['functional'])-1]:null;$projectTechnicalMax=$projectClassScope['technical']?$projectClassScope['technical'][count($projectClassScope['technical'])-1]:null;$projectDsvMax=$projectClassScope['dsv']?$projectClassScope['dsv'][count($projectClassScope['dsv'])-1]:null;$dsvLevels=provider_class_levels($db,'DSV');$dsvLabels=array_column($dsvLevels,'class_label','class_code');
    $projectClassObject=['functional_class'=>$projectFunctionalMax,'technical_class'=>$projectTechnicalMax,'dsv_class_code'=>$projectDsvMax];
    $standardProjectGroups=service_selection_groups($allStandardProjectServices,$projectClassScope['functional'],$projectClassScope['technical'],$projectClassScope['dsv']);
    $selectableStandardIds=service_selection_group_ids($standardProjectGroups);$selectableStandardIdMap=array_fill_keys($selectableStandardIds,true);
    foreach($standardProjectGroups[$dimension] as $class=>$classServices)$standardProjectGroups[$dimension][$class]=array_values(array_filter($classServices,fn($service)=>$inArea($service)&&(!$selectedObject||service_applies_to_rollout_object($service,$selectedObject))));
    $areaStandardServices=[];foreach($standardProjectGroups[$dimension] as $classServices)foreach($classServices as $service)$areaStandardServices[(int)$service['id']]=$service;
    $stmt=$db->prepare('SELECT ps.support_service_id FROM project_services ps JOIN support_services s ON s.id=ps.support_service_id WHERE ps.project_id=? AND s.is_standard=1');$stmt->execute([$projectId]);$selectedProjectServiceIds=array_map('intval',array_column($stmt->fetchAll(),'support_service_id'));
    $stmt=$db->prepare("SELECT s.* FROM support_services s JOIN project_services ps ON ps.support_service_id=s.id WHERE s.active=1 AND ps.project_id=? ORDER BY s.name COLLATE NOCASE");$stmt->execute([$projectId]);$projectServices=array_values(array_filter(enrich_support_services($db,$stmt->fetchAll()),fn($service)=>$inArea($service)&&(!$service['is_standard']||isset($selectableStandardIdMap[(int)$service['id']]))&&(!$selectedObject||service_applies_to_rollout_object($service,$selectedObject))));
    $classRank=static function(array $service)use($dimension):string{$codes=[];foreach((array)$service['class_codes'] as $entry){[$d,$c]=array_pad(explode(':',(string)$entry,2),2,'');if($d===$dimension)$codes[]=$c;}sort($codes,SORT_NATURAL);return $codes[0]??'~';};
    usort($projectServices,static fn($a,$b)=>strnatcmp($classRank($a),$classRank($b))?:strnatcasecmp((string)$a['name'],(string)$b['name']));
    $projectMandatory=mandatory_project_pairs($db,$projectId);
    $stmt=$db->prepare('SELECT * FROM project_support_matrix WHERE project_id=?');$stmt->execute([$projectId]);$projectMatrix=[];foreach($stmt as $cell)$projectMatrix[$cell['support_service_id']][$cell['provider_id']]=$cell;
    $stmt=$db->prepare('SELECT support_service_id,rollout_object_id,delivery_level,origin,origin_at FROM project_service_rollout_objects WHERE project_id=?');$stmt->execute([$projectId]);$serviceRolloutUsage=[];$serviceDeliveryLevels=[];$usageOrigins=[];foreach($stmt->fetchAll() as $mapping){$serviceRolloutUsage[(int)$mapping['support_service_id']][(int)$mapping['rollout_object_id']]=true;$serviceDeliveryLevels[(int)$mapping['support_service_id']][(int)$mapping['rollout_object_id']]=$mapping['delivery_level'];$usageOrigins[(int)$mapping['support_service_id']][(int)$mapping['rollout_object_id']]=origin_text($mapping['origin'],$mapping['origin_at']);}$deliveryMap=project_service_delivery_map($db,$projectId,$projectServices);$duplicates=duplicate_service_names($db,$projectId);
    // Block je Leistung: im Bereich Bankfachlich „Projekt (zentral)“ oder „Regionalverbände (regional)“
    $blockOf=static function(array $service)use($area,$selectedObject,$serviceDeliveryLevels,$deliveryMap):string{if($area!=='RV')return $area;if($selectedObject)return service_effective_delivery($service,$serviceDeliveryLevels[(int)$service['id']][(int)$selectedObject['id']]??null)==='central'?'central':'regional';return !empty($deliveryMap[(int)$service['id']]['rv_required'])?'regional':'central';};
    $blocks=$area==='RV'?['central'=>'Projekt (zentral)','regional'=>'Regionalverbände (regional)']:[$area=>$area==='FI'?'FI':'DSV'];
    $blockHints=['central'=>'Zentral durch das Projekt erbracht – die Regionalverbände werden dazu nicht befragt.','regional'=>'Regional durch die Regionalverbände erbracht – sie werden dazu befragt.','FI'=>'Leistungen der FI, immer zentral.','DSV'=>'Leistungen des DSV, immer zentral.'];
    $grouped=array_fill_keys(array_keys($blocks),[]);foreach($projectServices as $service)$grouped[$blockOf($service)][]=$service;
    $matrixServices=$selectedObject?array_values(array_filter($projectServices,fn($s)=>isset($serviceRolloutUsage[(int)$s['id']][(int)$selectedObject['id']]))):$projectServices;
    $matrixGrouped=array_fill_keys(array_keys($blocks),[]);foreach($matrixServices as $service)$matrixGrouped[$blockOf($service)][]=$service;
    $areaTitle=view_areas()[$area];$scopeText=$selectedObject?'Rolloutobjekt „'.$selectedObject['name'].'“':'alle Rolloutobjekte';?>
<div class="project-matrix-page"><div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-3"><div><a class="small text-secondary text-decoration-none" href="?page=project&id=<?=$projectId?>">← Projekt</a><h1 class="page-title h2 mt-2 mb-1"><?=e($project['name'])?></h1><div class="text-secondary">Projektleistungen auswählen, ihre Nutzung je Rolloutobjekt festlegen und Rückmeldungen zusammenführen</div></div><a class="btn btn-outline-secondary" href="?page=project&id=<?=$projectId?>">Projekt bearbeiten</a></div>
<?php render_view_selector($db,'matrix',$projectId,$objectId,$area,$allObjects,false,false);?>
<div class="class-color-legend mb-3" aria-label="Farblegende der Leistungsklassen"><span class="small fw-semibold text-muted me-1"><?=e($areaTitle)?></span><?php if($area==='RV'):foreach(['A','B','C','D'] as $class):?><span class="badge service-class-badge class-tone-functional-<?=strtolower($class)?>"><?=$class?></span><?php endforeach;elseif($area==='FI'):foreach(fi_class_codes() as $class):?><span class="badge service-class-badge class-tone-technical-<?=$class?>"><?=$class?></span><?php endforeach;else:foreach($dsvLevels as $index=>$level):?><span class="badge service-class-badge class-tone-technical-<?=min(3,$index+1)?>"><?=e($level['class_label'])?></span><?php endforeach;endif;?><span class="small text-muted ms-2">blass = niedrigere Klasse · kräftig = höhere Klasse</span></div>
<?php if($area==='RV'):?><div class="delivery-legend mb-3"><span class="delivery-key delivery-self">Selbst</span><span class="delivery-key delivery-other">Anderer RV</span><span class="delivery-key delivery-external">Externer DL</span><span class="delivery-key delivery-none">Keine Bereitstellung</span><span class="delivery-key delivery-open">Noch offen</span></div><?php endif;?>
<form method="post" data-track-dirty><?=csrf_field()?><input type="hidden" name="action" value="save_matrix"><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="scope_area" value="<?=e($area)?>"><input type="hidden" name="scope_object" value="<?=$objectId?>">
<?php
    $classOptions=['RV'=>array_combine(['A','B','C','D'],['A','B','C','D'])];$classOptions['FI']=['0'=>fi_class_label('0')];foreach(fi_class_codes() as $code)$classOptions['FI'][$code]=fi_class_label($code);$classOptions['DSV']=array_column(provider_class_levels($db,'DSV',true),'class_label','class_code');
    $classField=['RV'=>'functional_class','FI'=>'fi_class_code','DSV'=>'dsv_class_code'][$area];?>
<div class="card p-3 mb-4 matrix-full-width class-setter"><h2 class="h5 mb-1">Rolloutklasse <?=e($areaTitle)?></h2><p class="small text-secondary mb-3">Die Klasse bestimmt, welche Standardleistungen des Bereichs <?=e($areaTitle)?> für <?=$selectedObject?'das Rolloutobjekt':'das jeweilige Rolloutobjekt'?> passen (kumulativ). Sie wird mit „Ausschnitt speichern“ übernommen; danach erscheint die Leistungsauswahl passend zur neuen Klasse.<?=$area==='RV'?'':' „0“ bedeutet: keine Leistung dieses Bereichs erforderlich.'?></p>
<?php if(!$objects):?><div class="alert alert-light border small mb-0">Noch keine Rolloutobjekte vorhanden.</div><?php else:?><input type="hidden" name="class_present" value="1"><div class="row g-2">
<?php foreach($objects as $object):$current=(string)($object[$classField]??'');?><div class="<?=$selectedObject?'col-md-4':'col-md-6 col-xl-4'?>"><label class="form-label small fw-semibold mb-1"><?=e($object['name'])?></label><select class="form-select form-select-sm" name="object_class[<?=$object['id']?>]" aria-label="<?=e('Rolloutklasse '.$areaTitle.' für '.$object['name'])?>"><option value="">– noch keine Klasse –</option><?php foreach($classOptions[$area] as $code=>$label):?><option value="<?=e((string)$code)?>" <?=$current===(string)$code?'selected':''?>><?=e($area==='RV'?'Klasse '.$label:($area==='DSV'?$label:$label))?></option><?php endforeach;?></select></div><?php endforeach;?></div><?php endif;?></div>
<div class="card p-3 p-lg-4 mb-4 matrix-full-width"><h2 class="h5 mb-1"><?=e($areaTitle)?>: Standardleistungen für dieses Projekt auswählen</h2><p class="small text-secondary mb-3">Angezeigt werden die Leistungen des Katalogs <?=e($areaTitle)?>, die zu den Klassen <?=$selectedObject?'des gewählten Rolloutobjekts':'der Rolloutobjekte des Projekts'?> passen (kumulativ). Gespeichert wird nur diese Auswahl.</p>
<?php if($areaStandardServices):$labels=$area==='DSV'?$dsvLabels:[];foreach($standardProjectGroups[$dimension] as $class=>$classServices):if(!$classServices)continue;$class=(string)$class;$displayClass=$labels[$class]??$class;$tone=$dimension==='functional'?'functional-'.strtolower($class):'technical-'.min(3,max(1,(int)preg_replace('/\D+/','',(string)$class)));?><div class="service-selection-class mb-4"><div class="service-selection-class-header"><span class="catalog-group-class class-tone-<?=$tone?>"><?=e($displayClass)?></span><span class="fw-semibold">Klasse <?=e($displayClass)?></span><span class="small text-secondary"><?=count($classServices)?> <?=count($classServices)===1?'Leistung':'Leistungen'?></span></div><div class="row row-cols-1 row-cols-md-2 row-cols-xl-3 row-cols-xxl-4 g-2 mt-1">
<?php foreach($classServices as $service):?><div class="col"><label class="form-check service-option border rounded p-2 ps-5 h-100"><input class="form-check-input" type="checkbox" name="project_standard_service[]" value="<?=$service['id']?>" data-service-selection="<?=$service['id']?>" <?=in_array((int)$service['id'],$selectedProjectServiceIds,true)?'checked':''?>><span class="fw-semibold"><?=e($service['name'])?></span><span class="service-class-badges mt-1"><?=service_class_badges($service)?></span><?php if($service['description']):?><span class="d-block small text-secondary mt-1"><?=e($service['description'])?></span><?php endif;?></label></div><?php endforeach;?></div></div><?php endforeach;?>
<?php foreach(array_keys($areaStandardServices) as $shownId):?><input type="hidden" name="shown_standard[]" value="<?=$shownId?>"><?php endforeach;?>
<?php else:?><div class="alert alert-light border small mb-0"><?php if(!$projectFunctionalMax&&!$projectTechnicalMax&&!$projectDsvMax):?>Für dieses Projekt ist noch keine Rolloutklasse über seine Rolloutobjekte festgelegt. Sobald mindestens ein Rolloutobjekt klassifiziert ist, erscheinen hier die kumulativ passenden Unterstützungsleistungen.<?php else:?>Im Katalog <?=e($areaTitle)?> sind für die ermittelten Rolloutklassen keine passenden Standardleistungen hinterlegt.<?php endif;?></div><?php endif;?></div>
<div class="card p-3 mb-4 matrix-full-width"><h2 class="h5 mb-1">Nutzung je Rolloutobjekt – <?=e($scopeText)?></h2><p class="small text-secondary mb-3">Angehakt wird, bei welchen Rolloutobjekten die Projektleistung genutzt wird.<?php if($area==='RV'):?> Die Auswahl darunter legt fest, ob sie dort <strong>regional</strong> (durch die Regionalverbände, die dazu befragt werden) oder <strong>zentral</strong> (durch das Projekt) erbracht wird; nach dem Speichern erscheint die Leistung im passenden Block.<?php endif;?></p><?php if(!$objects):?><div class="alert alert-light border small mb-0">Noch keine Rolloutobjekte vorhanden.</div><?php elseif(!$projectServices):?><div class="alert alert-light border small mb-0">Bitte zuerst oben mindestens eine Standardleistung auswählen und speichern oder eine zusätzliche Projektleistung anlegen.</div><?php else:?><div class="table-responsive"><table class="table table-sm table-bordered align-middle mb-0"><thead><tr><th>Projektleistung</th><?php foreach($objects as $object):?><th class="text-center"><span class="d-block"><?=e($object['name'])?></span><span class="small fw-normal text-secondary"><?=e(class_label($object))?></span></th><?php endforeach;?></tr></thead>
<?php foreach($blocks as $blockKey=>$blockTitle):?><tbody><tr class="matrix-block-head matrix-block-<?=e(strtolower($blockKey))?>"><th colspan="<?=count($objects)+1?>"><?=e($blockTitle)?> <span class="fw-normal small text-secondary ms-2"><?=e($blockHints[$blockKey])?></span></th></tr><?php if(!$grouped[$blockKey]):?><tr><td colspan="<?=count($objects)+1?>" class="small text-secondary">Keine Leistungen in diesem Block.</td></tr><?php endif;?><?php foreach($grouped[$blockKey] as $service):?><tr><th><input type="hidden" name="shown_usage[]" value="<?=$service['id']?>"><span class="fw-semibold"><?=e($service['name'])?></span><span class="service-class-badges mt-1"><?=service_class_badges($service)?></span></th><?php foreach($objects as $object):$applicable=service_applies_to_rollout_object($service,$object);?><td class="text-center"><?php if($applicable&&!empty($service['always_included'])):?><input class="form-check-input" type="checkbox" checked disabled title="Immer enthalten – nicht abwählbar" aria-label="<?=e($service['name'].' für '.$object['name'].' (immer enthalten)')?>"><?php elseif($applicable):?><input class="form-check-input" type="checkbox" name="service_rollout[<?=$service['id']?>][<?=$object['id']?>]" value="1" <?=isset($serviceRolloutUsage[$service['id']][$object['id']])?'checked':''?> aria-label="<?=e($service['name'].' für '.$object['name'])?>"><?php else:?><span class="text-secondary" title="Für die Klassen dieses Rolloutobjekts nicht passend">–</span><?php endif;?><?php if($applicable&&service_regional_capable($service)):$effective=service_effective_delivery($service,$serviceDeliveryLevels[$service['id']][$object['id']]??null);?><select class="form-select form-select-sm mt-1 delivery-level-select delivery-level-<?=$effective?>" name="service_delivery[<?=$service['id']?>][<?=$object['id']?>]" aria-label="<?=e('Erbringung '.$service['name'].' für '.$object['name'])?>"><option value="regional" <?=$effective==='regional'?'selected':''?>>regional</option><option value="central" <?=$effective==='central'?'selected':''?>>zentral</option></select><?php endif;?><?php if(($usageOrigins[$service['id']][$object['id']]??'')!==''):?><div class="origin-note"><?=e($usageOrigins[$service['id']][$object['id']])?></div><?php endif;?><?=duplicate_badge($duplicates[(int)$object['id']][(int)$service['id']]??[])?></td><?php endforeach;?></tr><?php endforeach;?></tbody><?php endforeach;?></table></div><?php endif;?></div>
<?php if($providers):?><div class="card p-3 mb-4 matrix-full-width"><h2 class="h5 mb-1">Ansprechpartner <?=$area==='RV'?'der Regionalverbände':($area==='FI'?'der FI':'des DSV')?></h2><p class="small text-secondary">Je Projekt wird für jeden Leistungserbringer genau ein Ansprechpartner hinterlegt.</p><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Leistungserbringer</th><th>Ansprechpartner</th><th>Telefonnummer</th></tr></thead><tbody><?php foreach($providers as $provider):$contact=$projectContacts[$provider['id']]??null;?><tr><td class="fw-semibold"><?=e($provider['name'])?></td><td><input class="form-control form-control-sm" name="project_contact[<?=$provider['id']?>][contact_name]" value="<?=e($contact['contact_name']??'')?>" placeholder="Name"></td><td><input type="tel" class="form-control form-control-sm" name="project_contact[<?=$provider['id']?>][contact_phone]" value="<?=e($contact['contact_phone']??'')?>" placeholder="Telefonnummer"></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<div class="card matrix-wrap"><table class="table table-bordered matrix-table align-middle mb-0"><thead><tr><th>Unterstützungsleistung<?=$selectedObject?' <span class="fw-normal small text-secondary">(genutzt bei „'.e($selectedObject['name']).'“)</span>':''?></th><?php foreach($providers as $provider): ?><th class="text-center"><?=e($provider['name'])?></th><?php endforeach; ?></tr></thead>
<?php foreach($blocks as $blockKey=>$blockTitle):?><tbody><tr class="matrix-section matrix-block-head matrix-block-<?=e(strtolower($blockKey))?>"><th colspan="<?=count($providers)+1?>"><span class="badge text-bg-dark me-2"><?=e($blockTitle)?></span><span class="fw-normal small"><?=e($blockHints[$blockKey])?></span><?php if($blockKey!=='central'):?> <a class="btn btn-sm btn-outline-dark ms-3" href="?page=custom-service&project_id=<?=$projectId?>">+ Zusätzliche Projektleistung</a><?php endif;?></th></tr>
<?php if(!$matrixGrouped[$blockKey]): ?><tr><td colspan="<?=count($providers)+1?>" class="text-secondary py-3 small"><?=$selectedObject?'Keine Leistung dieses Blocks ist am gewählten Rolloutobjekt angehakt.':'Keine Leistungen in diesem Block.'?></td></tr><?php else: foreach($matrixGrouped[$blockKey] as $service){$rvRequired=$blockKey!=='central';if($rvRequired||$area!=='RV'):?><input type="hidden" name="shown_cells[]" value="<?=$service['id']?>"><?php endif;render_matrix_service_row($service,$providers,$projectMatrix,'project_cell',$projectMandatory,'project-'.$service['id'],$projectId,0,$projectClassObject,$rvRequired);}endif; ?>
</tbody><?php endforeach;?></table></div><div class="mt-3 d-flex gap-2 flex-wrap"><button class="btn btn-primary">Angezeigten Ausschnitt speichern</button><a class="btn btn-outline-secondary" href="?page=catalog">Standardkatalog öffnen</a><span class="small text-secondary align-self-center">Gespeichert wird nur der Bereich <?=e($areaTitle)?> für <?=e($scopeText)?>; andere Bereiche und Objekte bleiben unverändert.</span></div></form></div><script>(()=>{const update=select=>{const cell=select.closest('[data-delivery-cell]');if(!cell)return;cell.dataset.deliveryState=select.value||'open';cell.querySelector('[data-delivery-other]').hidden=select.value!=='other_rv';cell.querySelector('[data-delivery-external]').hidden=select.value!=='external';};document.querySelectorAll('[data-delivery-mode]').forEach(select=>{update(select);select.addEventListener('change',()=>update(select));});document.querySelectorAll('[data-service-selection]').forEach(box=>box.addEventListener('change',()=>{document.querySelectorAll('[data-service-selection="'+box.dataset.serviceSelection+'"]').forEach(peer=>peer.checked=box.checked);}));})();</script><?php }

function render_matrix_service_row(array $service,array $providers,array $matrix,string $prefix,array $mandatoryPairs,string $idPrefix,int $projectId,int $objectId,?array $object,bool $rvRequired=true): void {
    $classLabel=support_service_class_label($service);$requiresDelivery=!empty($service['requires_delivery_source']); ?>
<tr><td><strong><?=e($service['name'])?></strong> <span class="badge rounded-pill text-bg-<?=$service['is_standard']?'secondary':'warning'?>"><?=$service['is_standard']?'Standard':'zusätzlich'?></span>
<?php if(!$service['is_standard']):?><a class="small ms-1" href="?page=custom-service&id=<?=$service['id']?>&project_id=<?=$projectId?><?=$objectId?'&object_id='.$objectId:''?>">Bearbeiten</a><?php endif;?>
<?php if($classLabel!==''):?><div class="service-class-badges mt-1"><?=service_class_badges($service)?></div><?php endif;?>
<div class="mt-1"><?=service_flag_badges($service)?></div><?php if(empty($service['schedule_relevant'])):?><div><span class="badge text-bg-light border mt-1">Kein Termin/Zeitraum erforderlich</span></div><?php endif;?>
<?php if($service['description']):?><div class="small text-secondary mt-1"><?=e($service['description'])?></div><?php endif;?></td>
<?php foreach($providers as $provider):if(!service_applies_to_provider($service,$provider,$object)):?><td class="matrix-not-applicable text-center" title="Für diesen Leistungserbringer nicht vorgesehen">–</td><?php continue;endif;if($provider['type']==='RV'&&!$rvRequired):?><td class="matrix-not-applicable text-center small text-secondary" title="Zentral durch das Projekt erbracht – keine Angabe der Regionalverbände nötig">zentral</td><?php continue;endif;
    $cell=$matrix[$service['id']][$provider['id']]??null;$isMandatory=isset($mandatoryPairs[$service['id']][$provider['id']]);$scheduleRelevant=!empty($service['schedule_relevant']);$field=$prefix.'['.$service['id'].']['.$provider['id'].']';$detailsId='details-'.$idPrefix.'-'.$provider['id'];$isRv=$provider['type']==='RV';$useDelivery=$isRv&&$requiresDelivery&&!$isMandatory;$mode=normalize_delivery_mode((string)($cell['delivery_mode']??''));$partner=(string)($cell['delivery_partner']??'');$hasDetails=trim((string)($cell['note']??''))!==''||($scheduleRelevant&&trim((string)($cell['schedule']??''))!==''); ?>
<td class="text-center <?=$useDelivery?'delivery-cell':''?>" <?=$useDelivery?'data-delivery-cell data-delivery-state="'.e($mode?:'open').'"':''?>>
<?php if($useDelivery):?><select class="form-select form-select-sm delivery-mode" name="<?=$field?>[delivery_mode]" data-delivery-mode aria-label="Bereitstellungsart"><option value="" <?=$mode===''?'selected':''?>>Noch offen</option><option value="self" <?=$mode==='self'?'selected':''?>>Selbst</option><option value="other_rv" <?=$mode==='other_rv'?'selected':''?>>Anderer RV</option><option value="external" <?=$mode==='external'?'selected':''?>>Externer DL</option><?php if(!$isMandatory):?><option value="none" <?=$mode==='none'?'selected':''?>>Keine Bereitstellung</option><?php endif;?></select><div class="delivery-partner mt-2" data-delivery-other><label class="small text-secondary">Welcher RV?</label><select class="form-select form-select-sm" name="<?=$field?>[delivery_partner_other_rv]"><option value="">– auswählen –</option><?php foreach($providers as $otherProvider)if($otherProvider['type']==='RV'&&(int)$otherProvider['id']!==(int)$provider['id']):?><option value="<?=e($otherProvider['name'])?>" <?=$mode==='other_rv'&&$partner===$otherProvider['name']?'selected':''?>><?=e($otherProvider['name'])?></option><?php endif;?></select></div><div class="delivery-partner mt-2" data-delivery-external><label class="small text-secondary">Welcher Dienstleister?</label><input class="form-control form-control-sm" name="<?=$field?>[delivery_partner_external]" value="<?=e($mode==='external'?$partner:'')?>" placeholder="Name des Dienstleisters"></div><?php else:?><input class="matrix-check" type="checkbox" name="<?=$field?>[offered]" <?=$isMandatory||($cell&&$cell['offered'])?'checked':''?> <?=$isMandatory?'disabled title="Verpflichtende Basisleistung oder für alle zuständigen Leistungserbringer vorgegeben"':''?>><?php endif;?>
<button type="button" class="btn btn-link btn-sm p-1 d-block mx-auto <?=$hasDetails?'fw-bold text-danger':'text-secondary'?>" data-bs-toggle="collapse" data-bs-target="#<?=$detailsId?>"><?=$scheduleRelevant?'Termin / Bemerkung':'Bemerkung'?></button><div class="collapse mt-2 text-start matrix-details" id="<?=$detailsId?>"><?php if($scheduleRelevant):?><label class="small text-secondary">Termin / Zeitraum</label><input class="form-control form-control-sm mb-2" name="<?=$field?>[schedule]" value="<?=e($cell['schedule']??'')?>" placeholder="z. B. Oktober 2026"><?php endif;?><label class="small text-secondary">Bemerkung</label><textarea class="form-control form-control-sm" rows="2" name="<?=$field?>[note]" placeholder="Bemerkung zur Unterstützungsleistung"><?=e($cell['note']??'')?></textarea></div><?php $originNote=origin_text($cell['origin']??null,$cell['origin_at']??null);if($originNote!==''):?><div class="origin-note"><?=e($originNote)?></div><?php endif;?></td>
<?php endforeach;?></tr><?php }

