d><td class="small text-secondary"><?=e(implode(' · ',array_keys($group['notes'])))?></td><td class="text-nowrap"><form method="post" class="d-inline-flex gap-2 align-items-center"><?=csrf_field()?><input type="hidden" name="action" value="accept_catalog_suggestion"><input type="hidden" name="ids" value="<?=e($groupIds)?>"><?php if($existingName===null):?><select class="form-select form-select-sm" name="class_code" required aria-label="Ab Klasse"><?php foreach($suggestionLevels[$group['provider_type']]??[] as $level):?><option value="<?=e((string)$level['class_code'])?>" <?=(string)$level['class_code']===$group['class_code']?'selected':''?>><?=e((string)$level['class_label'])?></option><?php endforeach;?></select><?php endif;?><button class="btn btn-sm btn-primary"><?=$existingName===null?'In Katalog übernehmen':'Zuordnen'?></button></form> <form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="action" value="reject_catalog_suggestion"><input type="hidden" name="ids" value="<?=e($groupIds)?>"><button class="btn btn-sm btn-outline-secondary">Ablehnen</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
