/** Grafik: Kombinationen aus Rolloutklasse Bankfachlich und den Klassen von FI bzw. DSV, mit Anzahl der Rolloutobjekte je Kombination. */
/**
 * Katalog einer Leistung aus dem Formular: genau ein Anbieter (Bankfachlich/RV, FI oder DSV); Klassen anderer Kataloge entfallen.
 * Noch mehrfach zugeordnete Leistungen behalten ihre Zuordnung, bis sie über die Aufräumseite getrennt werden.
 */
function posted_catalog_targets(PDO $db,int $id,string $name,?int $projectId,array &$functional,array &$technical,array &$dsvClasses): array {
    if($id){$current=enrich_support_services($db,[['id'=>$id]])[0];if(count((array)$current['provider_targets'])>1)return array_values((array)$current['provider_targets']);}
    $target=post_string('provider_target');if(!in_array($target,['RV','FI','DSV'],true))throw new RuntimeException('Bitte den Katalog wählen: Bankfachlich, FI oder DSV.');
    if($target!=='RV')$functional=[];if($target!=='FI')$technical=[];if($target!=='DSV')$dsvClasses=[];
    if($taken=service_name_taken($db,$name,$target,$id,$projectId))throw new RuntimeException('Im Katalog '.catalog_type_label($target).' gibt es bereits eine Leistung „'.$taken['name'].'“'.(empty($taken['is_standard'])?' in diesem Projekt':'').'. Bitte einen anderen Namen wählen oder die vorhandene Leistung verwenden.');
    return [$target];
}

/** Auswahl des Katalogs im Editor; bei noch mehrfach zugeordneten Leistungen gesperrt mit Hinweis auf die Aufräumseite. */
function render_catalog_choice(array $service): void {
    $targets=(array)($service['provider_targets']??[]);$locked=!empty($service['id'])&&count($targets)>1;$current=$locked?'':($targets[0]??'');?>
<div><label class="form-label d-block fw-semibold">Katalog / Anbieter</label><?php foreach(['RV'=>'Bankfachlich (Regionalverbände bzw. zentral durch das Projekt)','FI'=>'FI','DSV'=>'DSV'] as $target=>$label):?><label class="form-check form-check-inline"><input class="form-check-input" type="radio" name="provider_target" value="<?=$target?>" data-catalog-choice <?=$current===$target?'checked':''?> <?=$locked?'disabled':'required'?>> <?=e($label)?></label><?php endforeach;?>
<?php if($locked):?><div class="alert alert-warning small mt-2 mb-0">Diese Leistung ist noch mehreren Anbietern zugeordnet (<?=e(implode(', ',array_map('catalog_type_label',$targets)))?>). Bitte über <a href="?page=catalog-cleanup">Mehrfach zugeordnete Leistungen aufräumen</a> trennen. Bis dahin bleiben die Zuordnungen beim Speichern unverändert.</div><?php else:?><div class="form-text">Jede Leistung gehört genau einem Katalog. Gleiche Namen sind in verschiedenen Katalogen erlaubt, z. B. „Kickoff“ bankfachlich und „Kickoff“ der FI.</div><?php endif;?></div>
<?php }

/** Leistungen, die noch mehreren Anbietern (RV, FI, DSV) zugeordnet sind. */
function multi_target_services(PDO $db): array {
    $rows=$db->query("SELECT s.*,p.name project_name FROM support_services s LEFT JOIN projects p ON p.id=s.project_id WHERE (SELECT COUNT(*) FROM support_service_provider_targets t WHERE t.support_service_id=s.id)>1 ORDER BY s.is_standard DESC,s.name COLLATE NOCASE")->fetchAll();
    return enrich_support_services($db,$rows);
}

/**
 * Trennt mehrfach zugeordnete Leistungen. „split“: je Anbieter ein eigener Eintrag gleichen Namens; der bankfachliche
 * (sonst FI-)Eintrag behält die ID. Klassen, Zuständigkeit und Rückmeldungen des jeweiligen Anbieters wandern mit,
 * Nutzungen an Rolloutobjekten nur dort, wo der Anbieter das Objekt in seiner Rückmeldung genannt hat.
 * „RV“/„FI“/„DSV“: nur dieser Anbieter bleibt; Klassen und Rückmeldungen der anderen entfallen.
 */
function apply_catalog_cleanup(PDO $db,array $actions,bool $manageTransaction=true): array {
    $result=['split'=>0,'kept'=>0];if($manageTransaction)$db->beginTransaction();
    $providerIds=[];foreach($db->query('SELECT id,type FROM providers')->fetchAll() as $provider)$providerIds[(string)$provider['type']][]=(int)$provider['id'];
    $in=static fn(array $ids):string=>$ids?implode(',',array_map('intval',$ids)):'0';
    foreach($actions as $serviceId=>$decision){
        $serviceId=(int)$serviceId;$stmt=$db->prepare('SELECT * FROM support_services WHERE id=?');$stmt->execute([$serviceId]);$row=$stmt->fetch();if(!$row)continue;
        $service=enrich_support_services($db,[$row])[0];$targets=array_values(array_intersect(['RV','FI','DSV'],(array)$service['provider_targets']));if(count($targets)<2)continue;
        if($decision==='split'){
            $primary=$targets[0];
            foreach(array_slice($targets,1) as $target){
                $dimension=catalog_dimension($target);$providers=$in($providerIds[$target]??[]);
                $db->prepare('INSERT INTO support_services(name,description,is_standard,project_id,mandatory_for_all,always_included,default_delivery,schedule_relevant,active,sort_order) VALUES(?,?,?,?,0,?,?,?,?,?)')->execute([$row['name'],$row['description'],$row['is_standard'],$row['project_id'],$row['always_included'],'regional',$row['schedule_relevant'],$row['active'],$row['sort_order']]);$newId=(int)$db->lastInsertId();
                $db->prepare('UPDATE support_service_classes SET support_service_id=? WHERE support_service_id=? AND dimension=?')->execute([$newId,$serviceId,$dimension]);
                $db->prepare('UPDATE support_service_provider_targets SET support_service_id=? WHERE support_service_id=? AND provider_type=?')->execute([$newId,$serviceId,$target]);
                $projects=$db->query("SELECT DISTINCT project_id FROM project_support_matrix WHERE support_service_id=$serviceId AND provider_id IN ($providers) UNION SELECT DISTINCT project_id FROM rollout_object_support_matrix WHERE support_service_id=$serviceId AND provider_id IN ($providers)")->fetchAll(PDO::FETCH_COLUMN);
                if(empty($row['is_standard'])&&$row['project_id'])$projects[]=(int)$row['project_id'];
                foreach(array_unique(array_map('intval',$projects)) as $projectId)$db->prepare('INSERT OR IGNORE INTO project_services(project_id,support_service_id) VALUES(?,?)')->execute([$projectId,$newId]);
                $db->exec("INSERT OR IGNORE INTO project_service_rollout_objects(project_id,support_service_id,rollout_object_id) SELECT DISTINCT u.project_id,$newId,u.rollout_object_id FROM project_service_rollout_objects u WHERE u.support_service_id=$serviceId AND EXISTS (SELECT 1 FROM rollout_object_support_matrix m WHERE m.support_service_id=$serviceId AND m.rollout_object_id=u.rollout_object_id AND m.provider_id IN ($providers))");
                $db->exec("UPDATE rollout_object_support_matrix SET support_service_id=$newId WHERE support_service_id=$serviceId AND provider_id IN ($providers)");
                $db->exec("UPDATE project_support_matrix SET support_service_id=$newId WHERE support_service_id=$serviceId AND provider_id IN ($providers)");
                prune_invalid_service_rollout_usage($db,null,$newId);
            }
            if($primary!=='RV')$db->prepare("UPDATE support_services SET default_delivery='regional' WHERE id=?")->execute([$serviceId]);
            prune_invalid_service_rollout_usage($db,null,$serviceId);$result['split']++;
        }elseif(in_array($decision,$targets,true)){
            foreach(array_diff($targets,[$decision]) as $target){$providers=$in($providerIds[$target]??[]);$db->prepare('DELETE FROM support_service_classes WHERE support_service_id=? AND dimension=?')->execute([$serviceId,catalog_dimension($target)]);$db->prepare('DELETE FROM support_service_provider_targets WHERE support_service_id=? AND provider_type=?')->execute([$serviceId,$target]);$db->exec("DELETE FROM rollout_object_support_matrix WHERE support_service_id=$serviceId AND provider_id IN ($providers)");$db->exec("DELETE FROM project_support_matrix WHERE support_service_id=$serviceId AND provider_id IN ($providers)");}
            if($decision!=='RV')$db->prepare("UPDATE support_services SET default_delivery='regional' WHERE id=?")->execute([$serviceId]);
            prune_invalid_service_rollout_usage($db,null,$serviceId);$result['kept']++;
        }
    }
    sync_mandatory_services($db);if($manageTransaction)$db->commit();return $result;
}

function render_catalog_cleanup(PDO $db): void {
    $services=multi_target_services($db);$classLabel=static function(array $service,string $target):string{$dimension=catalog_dimension($target);$codes=[];foreach((array)$service['class_codes'] as $entry){[$d,$c]=array_pad(explode(':',(string)$entry,2),2,'');if($d===$dimension)$codes[]=$target==='FI'?fi_class_label($c):($target==='DSV'?(string)(($service['dsv_class_labels']??[])[$c]??$c):$c);}return $codes?'ab '.$codes[0]:'ohne Klasse';};
    $stats=static function(PDO $db,int $id):array{$q=static fn(string $sql)=>(int)$db->query($sql)->fetchColumn();return ['projects'=>$q("SELECT COUNT(*) FROM project_services WHERE support_service_id=$id"),'objects'=>$q("SELECT COUNT(*) FROM project_service_rollout_objects WHERE support_service_id=$id"),'RV'=>$q("SELECT COUNT(*) FROM project_support_matrix m JOIN providers p ON p.id=m.provider_id WHERE p.type='RV' AND m.support_service_id=$id"),'FI'=>$q("SELECT COUNT(*) FROM rollout_object_support_matrix m JOIN providers p ON p.id=m.provider_id WHERE p.type='FI' AND m.support_service_id=$id"),'DSV'=>$q("SELECT COUNT(*) FROM rollout_object_support_matrix m JOIN providers p ON p.id=m.provider_id WHERE p.type='DSV' AND m.support_service_id=$id")];}; ?>
<div class="mb-4"><a class="small text-secondary text-decoration-none" href="?page=catalog">← Standardkatalog</a><h1 class="page-title h2 mt-2 mb-1">Mehrfach zugeordnete Leistungen aufräumen</h1><p class="text-secondary mb-0">Jede Leistung gehört künftig genau einem Katalog: Bankfachlich, FI oder DSV. Diese Leistungen sind noch mehreren zugeordnet. Entscheide je Leistung; vor dem Speichern zeigt die Vorschau alle Änderungen.</p></div>
<?php if(!$services):?><div class="alert alert-success">✓ Alle Leistungen sind genau einem Katalog zugeordnet. Hier ist nichts mehr zu tun.</div><?php return;endif;?>
<div class="alert alert-light border small"><strong>Aufteilen:</strong> Je Anbieter entsteht ein eigener Eintrag gleichen Namens mit dessen Klasse. Rückmeldungen von FI bzw. DSV wandern zum neuen Eintrag, ebenso die Nutzung an den Rolloutobjekten, die FI bzw. DSV genannt haben; die Auswahl des TPL bleibt beim bankfachlichen Eintrag. <strong>Nur … behalten:</strong> Die anderen Zuordnungen samt deren Klassen und Rückmeldungen entfallen.</div>
<form method="post" class="card p-3 p-lg-4"><?=csrf_field()?><input type="hidden" name="action" value="catalog_cleanup_preview"><div class="table-responsive"><table class="table align-middle mb-3"><thead><tr><th>Leistung</th><th>Heute zugeordnet</th><th>Verwendung</th><th style="min-width:16rem">Entscheidung</th></tr></thead><tbody>
<?php foreach($services as $service):$targets=array_values(array_intersect(['RV','FI','DSV'],(array)$service['provider_targets']));$st=$stats($db,(int)$service['id']);?><tr><td><strong><?=e($service['name'])?></strong><div class="small text-secondary"><?=$service['is_standard']?'Standardleistung':'Zusätzliche Leistung · Projekt '.e((string)$service['project_name'])?></div></td>
<td><?php foreach($targets as $target):?><span class="badge text-bg-light border me-1"><?=e(catalog_type_label($target))?> · <?=e($classLabel($service,$target))?></span><?php endforeach;?></td>
<td class="small"><?=$st['projects']?> Projekt(e), <?=$st['objects']?> Objektzuordnung(en)<br><span class="text-secondary">Rückmeldungen: RV <?=$st['RV']?> · FI <?=$st['FI']?> · DSV <?=$st['DSV']?></span></td>
<td><select class="form-select form-select-sm" name="decision[<?=$service['id']?>]"><option value="">– später entscheiden –</option><option value="split">Aufteilen: je Anbieter ein Eintrag</option><?php foreach($targets as $target):?><option value="<?=$target?>">Nur <?=e(catalog_type_label($target))?> behalten</option><?php endforeach;?></select></td></tr><?php endforeach;?>
</tbody></table></div><div class="d-flex flex-wrap gap-2"><button class="btn btn-primary">Änderungen in der Vorschau anzeigen</button><button type="button" class="btn btn-outline-secondary" onclick="this.form.querySelectorAll('select').forEach(s=>s.value='split')">Alle auf „Aufteilen“ setzen</button></div></form>
<?php }

function render_class_combinations(PDO $db): void {
    $objects=enrich_rollout_objects($db,$db->query('SELECT * FROM rollout_objects')->fetchAll());$functional=['A','B','C','D'];
    $schemes=['FI'=>provider_class_levels($db,'FI',true),'DSV'=>provider_class_levels($db,'DSV',true)];$total=count($objects); ?>
<section class="card p-4" style="max-width:1300px"><h2 class="h5 mb-1">Kombinationsmöglichkeiten der Klassen</h2><p class="small text-secondary mb-3">Jedes Rolloutobjekt hat eine Rolloutklasse Bankfachlich (A–D) und je Verbunddienstleister eine eigene Klasse (0 = keine Verbundpartnerleistung). Alle Kombinationen sind zulässig. Die Zahl im Feld zeigt, wie viele Rolloutobjekte diese Kombination heute haben (<?=$total?> Rolloutobjekte insgesamt). Alle Klassen wirken kumulativ: Eine höhere Klasse enthält die Leistungen aller niedrigeren.</p>
<div class="row g-4"><?php foreach($schemes as $type=>$levels):$field=$type==='FI'?'fi_class_code':'dsv_class_code';$counts=[];$max=0;foreach($objects as $object){$f=(string)($object['functional_class']??'');$c=(string)($object[$field]??'');$counts[$f][$c]=($counts[$f][$c]??0)+1;}foreach($counts as $row)foreach($row as $n)$max=max($max,$n);?>
<div class="col-xl-6"><h3 class="h6">Bankfachlich × <?=$type?></h3><div class="table-responsive"><table class="table table-sm text-center align-middle combo-table mb-2"><thead><tr><th class="text-start">Bankfachlich ↓ / <?=$type?> →</th><?php foreach($levels as $level):?><th><?=e((string)$level['class_code']==='0'?'0':(string)$level['class_label'])?></th><?php endforeach;?></tr></thead><tbody>
<?php foreach($functional as $fIndex=>$f):?><tr><th class="text-start"><span class="class-chip">Klasse <?=$f?></span><div class="small fw-normal text-secondary">enthält <?=implode(', ',array_slice($functional,0,$fIndex+1))?></div></th><?php foreach($levels as $lIndex=>$level):$n=$counts[$f][(string)$level['class_code']]??0;$alpha=$max?0.12+0.68*$n/$max:0;$shade=$fIndex+$lIndex;?><td><div class="combo-cell <?=$n?'':'combo-empty'?>" style="<?=$n?'background:rgba(227,6,19,'.round($alpha,2).');color:'.($alpha>0.5?'#fff':'#252525'):''?>" title="Bankfachlich <?=$f?> mit <?=$type?> <?=e((string)$level['class_label'])?>: <?=$n?> Rolloutobjekt(e)"><span class="combo-code"><?=$f?> / <?=e((string)$level['class_code']==='0'?'0':(string)$level['class_label'])?></span><strong><?=$n?></strong></div></td><?php endforeach;?></tr><?php endforeach;?>
</tbody></table></div><?php $unclassified=0;foreach($objects as $object)if((string)($object['functional_class']??'')===''||(string)($object[$field]??'')==='')$unclassified++;if($unclassified):?><p class="small text-secondary mb-0"><?=$unclassified?> Rolloutobjekt(e) ohne vollständige Klassenangabe sind nicht enthalten.</p><?php endif;?></div>
<?php endforeach;?></div></section>
<?php }

