eld?>" rows="6" required><?=e(implode("\n",array_column($schemeLevels,'class_label')))?></textarea><button class="btn btn-primary align-self-start"><?=$schemeType?>-Klassenschema speichern</button></form></div><?php endforeach;?></div>
