function catalog_maintenance_workbook(PDO $db,string $providerType): array {
    if(!in_array($providerType,['RV','FI','DSV'],true))throw new RuntimeException('Ungültiger Katalogbereich.');
    if($providerType==='RV'){$dimension='functional';$levels=[['class_code'=>'A','class_label'=>'A'],['class_code'=>'B','class_label'=>'B'],['class_code'=>'C','class_label'=>'C'],['class_code'=>'D','class_label'=>'D']];}
    else{$dimension=$providerType==='FI'?'technical':'dsv';$levels=provider_class_levels($db,$providerType);}
    $headers=['Leistung-ID','Unterstützungsleistung','Beschreibung'];foreach($levels as $level)$headers[]='Klasse '.(string)$level['class_label'];array_push($headers,'Zentral erbracht','Immer enthalten','Termin / Zeitraum relevant','Aktiv');
    $stmt=$db->prepare('SELECT s.* FROM support_services s JOIN support_service_provider_targets t ON t.support_service_id=s.id AND t.provider_type=? WHERE s.is_standard=1 ORDER BY s.name COLLATE NOCASE');$stmt->execute([$providerType]);$services=enrich_support_services($db,$stmt->fetchAll());$rows=[$headers];
    foreach($services as $service){$codes=[];foreach((array)$service['class_codes'] as $entry){[$entryDimension,$code]=array_pad(explode(':',(string)$entry,2),2,'');if($entryDimension===$dimension)$codes[]=$code;}$firstLevel=null;foreach($levels as $levelIndex=>$level){if(in_array((string)$level['class_code'],$codes,true)){$firstLevel=$levelIndex;break;}}$row=[(string)$service['id'],(string)$service['name'],(string)$service['description']];foreach($levels as $levelIndex=>$level)$row[]=$firstLevel!==null&&$levelIndex>=$firstLevel?'Ja':'Nein';array_push($row,($service['default_delivery']??'regional')==='central'?'Ja':'Nein',!empty($service['always_included'])?'Ja':'Nein',!empty($service['schedule_relevant'])?'Ja':'Nein',!empty($service['active'])?'Ja':'Nein');$rows[]=$row;}
    for($index=0;$index<20;$index++){$row=['','',''];foreach($levels as $_)$row[]='Nein';array_push($row,'Nein','Nein','Ja','Ja');$rows[]=$row;}
    $classStart=3;$classColumns=range($classStart,$classStart+count($levels)-1);$flagColumns=[$classStart+count($levels),$classStart+count($levels)+1,$classStart+count($levels)+2,$classStart+count($levels)+3];
    return ['rows'=>$rows,'legend'=>export_legend($db,$providerType),'class_columns'=>$classColumns,'flag_columns'=>$flagColumns,'provider_type'=>$providerType,'dimension'=>$dimension,'levels'=>$levels];
}

function download_catalog_maintenance(PDO $db,string $providerType): never {
    $labels=['RV'=>'Regionalverbaende','FI'=>'FI','DSV'=>'DSV'];$workbook=catalog_maintenance_workbook($db,$providerType);Xlsx::downloadBinary(Xlsx::catalogMaintenanceBinary($workbook),'Leistungskatalog-'.$labels[$providerType].'-'.date('d.m.Y').'.xlsx');
}

